<?php
/** TEMP PS S1612 run e5d — D: deploy darbalaukis v3.11 (4 b64 dalys, md5 + token sargai, gyvo failo sargas v3.10.6) + kliento-siuntos v1.2; T (naujas procesas): cron patikra, realus API #35421, simuliuoti Venipak įvykiai per `ps_venipak_ivykiai` #35438/#35440/#35421, laiškų gaudyklė prior. 4, Klausimų eilė loopback kaip testuotojas, paskyra Playwright kaip 5787 */
add_action('init', function(){
  if (!isset($_GET['ps_e5d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e5d'])); $o=array('v'=>'run e5d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  try{
  if($f==='D'){
    $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
    $c4='';
    $p1=@file_get_contents($bk.'/dl-v311.part1'); $p2=@file_get_contents($bk.'/dl-v311.part2'); $p3=@file_get_contents($bk.'/dl-v311.part3'); $o['parts']=array(strlen((string)$p1),strlen((string)$p2),strlen((string)$p3),strlen($c4));
    $code=base64_decode($p1.$p2.$p3.$c4,true); $o['bytes']=strlen((string)$code); $o['md5']=md5((string)$code);
    if ($o['md5']!=='2c8a1ec90092b4873ee53418be84f1ea') { $o['STOP']='md5 nesutampa'; $J($o); }
    try { token_get_all($code, TOKEN_PARSE); $o['token']='ok'; } catch (Throwable $e) { $o['STOP']='token: '.$e->getMessage(); $J($o); }
    $k=base64_decode('',true); $o['ks_bytes']=strlen((string)$k); $o['ks_md5']=md5((string)$k);
    if ($o['ks_md5']!=='fb5a0c084731f57eecd2faa069f3ef3b') { $o['STOP']='ks md5 nesutampa'; $J($o); }
    try { token_get_all($k, TOKEN_PARSE); $o['ks_token']='ok'; } catch (Throwable $e) { $o['STOP']='ks token: '.$e->getMessage(); $J($o); }
    $t=WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'; $o['buvo']=md5_file($t);
    if ($o['buvo']!=='770feb233b28fefb8a52968b6a290dd0') { $o['STOP']='gyvas ne v3.10.6 ('.$o['buvo'].')'; $J($o); }
    $kt=WPMU_PLUGIN_DIR.'/petshop-kliento-siuntos.php'; $o['ks_buvo']=md5_file($kt);
