    $o['backup']=copy($t,$bk.'/petshop-darbalaukis-v3106-BACKUP-'.date('Y-m-d').'.php'); $o['ks_backup']=copy($kt,$bk.'/petshop-kliento-siuntos-v11-BACKUP-'.date('Y-m-d').'.php');
    $o['rasyta']=file_put_contents($t,$code); $o['po']=md5_file($t); $o['ks_rasyta']=file_put_contents($kt,$k); $o['ks_po']=md5_file($kt);
    @unlink($bk.'/dl-v311.part1'); @unlink($bk.'/dl-v311.part2'); @unlink($bk.'/dl-v311.part3');
  }
  if($f==='T'){
    $o['versija']=Petshop_Darbalaukis::VERSIJA; $o['ks']=Petshop_Kliento_Siuntos::VERSIJA; $o['md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'); $o['ks_md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-kliento-siuntos.php');
    $o['cron_kada']=($n=wp_next_scheduled('ps_venipak_sekimas'))?gmdate('Y-m-d H:i:s',$n):null; $o['cron_sched']=wp_get_schedules()['ps_30min']??null; $o['cron_hook']=has_action('ps_venipak_sekimas');
    update_option('ps_e5_mail',array(),false);
