    $A=35421; $B=35438; $C=35440;
    $bk=function($id){ $x=wc_get_order($id); if(!$x) return null; return array('st'=>$x->get_status(),'cust'=>$x->get_customer_id(),'iss'=>(string)$x->get_meta('_ps_dalys_issiusta'),'reg'=>Petshop_Siuntos::sarasas($id),'sek'=>Petshop_Darbalaukis::sekimas($x),'griz'=>Petshop_Darbalaukis::grizta($x),'kl'=>array_map(function($s){ return $s['dalis'].' '.$s['busena'].' '.($s['pristatyta']??'').' '.implode('/',$s['numeriai']); },Petshop_Darbalaukis::kliento_siuntos($x))); };
    foreach(array($A,$B,$C) as $id){ $o['pries'][$id]=$bk($id); }
