    $o['r1_real']=Petshop_Darbalaukis::venipak_sekimas(array($A)); $o['r1_po']=$bk($A);
    // 2. Simuliacija (filtras): įvykiai pagal realią seką 106325241
    $E=function($k,$e,$t,$d,$pl=null){ return array('shipment_id'=>1,'pack_no'=>'','event'=>$e,'pack_status'=>$k,'pack_status_text'=>$t,'location'=>array('place'=>$pl,'address'=>null,'city'=>$pl,'lat'=>null,'lng'=>null),'date'=>$d,'date_iso'=>$d); };
    $cr=$E(0,'Shipment created','At sender','2026-09-04 09:00:00'); $rt=$E(1,'On route to terminal','On route to terminal','2026-09-04 10:00:00'); $at=$E(2,'At terminal','At terminal','2026-09-04 11:00:00','KAUNAS'); $ofd=$E(3,'Out for delivery','On route to receiver','2026-09-04 12:00:00','KAUNAS'); $dl=$E(9,'Delivered','Delivered','2026-09-04 13:00:00','Kauno Akropolio Venipak paštomatas'); $ret=$E(7,'Returning to sender','Returning to sender','2026-09-04 14:00:00','KAUNAS'); $nez=$E(4,'Delivery attempt failed','Delivery attempt failed','2026-09-04 12:30:00','KAUNAS');
    $SIM=array(); add_filter('ps_venipak_ivykiai',function($ev,$nr) use (&$SIM){ return isset($SIM[$nr])?$SIM[$nr]:array(); },10,2);
