    $bst=wc_get_order($B)->get_status(); $o['B_st']=$bst;
    if($bst==='processing' && !empty($nrB['prins']) && !empty($nrB['av'])){
      // 2a: prins terminale, av dar pas siuntėją → „Prins išsiuntė“ pats, laiškas „1 iš 2“
      $SIM=array($nrB['prins'][0]=>array($cr,$at), $nrB['av'][0]=>array($cr));
      $o['r2a']=Petshop_Darbalaukis::venipak_sekimas(array($B)); $o['r2a_po']=$bk($B); $o['r2a_mail']=count(get_option('ps_e5_mail',array()));
      // 2b: av pristatyta, prins pristatyta → „Kurjeris paėmė“ pats → completed, laiškas „2 iš 2“, abi Pristatyta
      $SIM=array($nrB['prins'][0]=>array($cr,$at,$ofd,$dl), $nrB['av'][0]=>array($cr,$rt,$at,$ofd,$dl));
      $o['r2b']=Petshop_Darbalaukis::venipak_sekimas(array($B)); $o['r2b_po']=$bk($B); $o['r2b_mail']=count(get_option('ps_e5_mail',array()));
      // 2c: kartojam — nieko naujo (pristatyti — nebeklausiam)
      $o['r2c']=Petshop_Darbalaukis::venipak_sekimas(array($B));
    } else { $o['B_praleista']='ne processing arba registras kitoks'; }
    // 3. #35440 (completed, av 3 numeriai, klientas 5787): 049 grįžta (k=7 tekstu), 050 nežinomas kodas 4, 051 pristatyta
    $regC=Petshop_Siuntos::sarasas($C); $nrC=array(); foreach($regC as $s){ $nrC[$s['sandelis']]=$s['numeriai']; } $o['nrC']=$nrC;
    if(!empty($nrC['av']) && count($nrC['av'])>=3){
      $SIM=array($nrC['av'][0]=>array($cr,$at,$ret), $nrC['av'][1]=>array($cr,$at,$nez), $nrC['av'][2]=>array($cr,$at,$dl));
      $o['r3']=Petshop_Darbalaukis::venipak_sekimas(array($C)); $o['r3_po']=$bk($C);
      $o['r3_notes']=array_map(function($n){ return mb_substr($n->content,0,160); },array_slice(wc_get_order_notes(array('order_id'=>$C,'limit'=>4)),0,4));
      $o['r3_again']=Petshop_Darbalaukis::venipak_sekimas(array($C)); // stop ir pristatyta nebeklausiami; 050 klausiamas, bet nieko naujo
    }
    // 4. #35421 (5787): prins V…046 pristatyta → paskyroje „Siunta 1 iš 2 · Pristatyta“
    $regA=Petshop_Siuntos::sarasas($A); $nrA=array(); foreach($regA as $s){ $nrA[$s['sandelis']]=$s['numeriai']; }
    if(!empty($nrA['prins'])){ $SIM=array($nrA['prins'][0]=>array($cr,$at,$ofd,$dl)); $o['r4']=Petshop_Darbalaukis::venipak_sekimas(array($A)); $o['r4_po']=$bk($A); }
    $o['ivykiai']=$wpdb->get_results($wpdb->prepare("SELECT uzsakymas, veiksmas, kanalas, kas_vardas, pastaba FROM {$p}ps_uzsakymu_ivykiai WHERE uzsakymas IN (%d,%d,%d) AND veiksmas LIKE 'venipak%%' OR (uzsakymas IN (%d,%d,%d) AND kanalas='venipak') ORDER BY id DESC LIMIT 12",$A,$B,$C,$A,$B,$C),ARRAY_A);
    $o['laiskai']=array_map(function($m){ return $m['to'].' | '.$m['s'].' | '.mb_substr($m['b'],0,200); },get_option('ps_e5_mail',array())); $o['dev_zurnalas']=count((array)get_option('ps_dev_pastas_zurnalas',array()));
    delete_option('ps_e5_mail');
    // 5. Klausimų eilė loopback kaip testuotojas (#35440 kortelė „Siunta grįžta“)
    $tu=get_user_by('login','testuotojas'); $o['testuotojas']=$tu?$tu->ID:null;
    $ck=function($uid){ $exp=time()+1800; $tok=WP_Session_Tokens::get_instance($uid)->create($exp); return array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'logged_in',$tok)))); };
    if($tu){ $r=wp_remote_get(admin_url('admin.php?page=ps-desk&eile=klausimai'),array('cookies'=>$ck($tu->ID),'timeout'=>90,'sslverify'=>false)); $b=is_wp_error($r)?'':wp_remote_retrieve_body($r);
      $o['klausimai']=array('code'=>is_wp_error($r)?$r->get_error_message():wp_remote_retrieve_response_code($r),'korteliu'=>substr_count($b,'dl-kortele eil'),'grizta_yra'=>strpos($b,'Siunta grįžta')!==false||strpos($b,'siunta grįžta')!==false);
      if(preg_match('/<div class="dl-kortele eil" data-id="'.$C.'".*?<\/div>/s',$b,$mm)) $o['klausimai']['kortele_35440']=trim(preg_replace('/\s+/',' ',wp_strip_all_tags($mm[0])));
      $r2=wp_remote_get(admin_url('admin.php?page=ps-desk&eile=visi&atidaryti='.$B),array('cookies'=>$ck($tu->ID),'timeout'=>90,'sslverify'=>false)); $b2=is_wp_error($r2)?'':wp_remote_retrieve_body($r2);
      $o['skydelis_B']=array('code'=>wp_remote_retrieve_response_code($r2),'venipak_tekstas'=>preg_match('/Venipak: [^"<]{0,120}/u',$b2,$m2)?$m2[0]:'nerasta');
    }
